<?php
namespace App\Http\Controllers\Api\V1;
use App\Models\{Customer,ProductVariant,SalesQuotation,SalesQuotationItem,SalesOrder,SalesOrderItem}; use App\Services\{AuthorizationService,SalesCalculationService,SalesDocumentService,SalesNumberService}; use App\Support\TenantContext; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
final class SalesQuotationController { public function index(Request $r){$q=SalesQuotation::where('tenant_id',app(TenantContext::class)->id())->with('customer')->latest();return response()->json(['data'=>$q->paginate(min($r->integer('per_page',25),100))]);} public function store(Request $r,AuthorizationService $a,SalesCalculationService $calc,SalesNumberService $numbers){$t=app(TenantContext::class)->id();abort_unless($a->allows($r->user(),$t,'sales.manage'),403);$d=$r->validate(['customer_id'=>'required|uuid','valid_until'=>'nullable|date','items'=>'required|array|min:1','items.*.variant_id'=>'required|uuid','items.*.quantity'=>'required|numeric|min:0.000001','items.*.unit_price'=>'required|numeric|min:0','items.*.discount_rate'=>'nullable|numeric|min:0|max:100','items.*.tax_rate'=>'nullable|numeric|min:0|max:100']);$customer=Customer::where('tenant_id',$t)->findOrFail($d['customer_id']);$lines=[];foreach($d['items'] as $item){abort_unless(ProductVariant::where('tenant_id',$t)->whereKey($item['variant_id'])->exists(),404);$lines[]=$calc->line($item);} $totals=$calc->totals($lines);$q=DB::transaction(function()use($d,$lines,$totals,$t,$r,$numbers){$q=SalesQuotation::create([...$totals,'tenant_id'=>$t,'customer_id'=>$d['customer_id'],'created_by'=>$r->user()->id,'number'=>$numbers->next($t,'quotation'),'valid_until'=>$d['valid_until']??null]);foreach($d['items'] as $i=>$item)SalesQuotationItem::create([...$lines[$i],'tenant_id'=>$t,'quotation_id'=>$q->id,'variant_id'=>$item['variant_id']]);return $q->load('items');});return response()->json(['data'=>$q],201);} public function transition(Request $r,SalesQuotation $quotation,SalesDocumentService $state){$t=app(TenantContext::class)->id();abort_unless($quotation->tenant_id===$t,404);$d=$r->validate(['state'=>'required|in:sent,accepted,rejected,expired']);$state->transition($quotation,'quotation',$d['state'],$r->user()->id);return response()->json(['data'=>$quotation->fresh()]);} public function convert(SalesQuotation $quotation,SalesDocumentService $state,SalesNumberService $numbers){$t=app(TenantContext::class)->id();abort_unless($quotation->tenant_id===$t,404);abort_unless($quotation->state==='accepted',422,'Only accepted quotations can be converted.');if($existing=SalesOrder::where('tenant_id',$t)->where('quotation_id',$quotation->id)->first())return response()->json(['data'=>$existing]);$order=DB::transaction(function()use($quotation,$t,$numbers){$o=SalesOrder::create(['tenant_id'=>$t,'customer_id'=>$quotation->customer_id,'quotation_id'=>$quotation->id,'created_by'=>auth()->id(),'number'=>$numbers->next($t,'order'),'state'=>'draft','subtotal'=>$quotation->subtotal,'discount_total'=>$quotation->discount_total,'tax_total'=>$quotation->tax_total,'total'=>$quotation->total]);foreach($quotation->items as $i)SalesOrderItem::create(['tenant_id'=>$t,'sales_order_id'=>$o->id,'variant_id'=>$i->variant_id,'ordered_quantity'=>$i->quantity,'unit_price'=>$i->unit_price,'discount_rate'=>$i->discount_rate,'tax_rate'=>$i->tax_rate,'line_subtotal'=>$i->line_subtotal,'discount_amount'=>$i->discount_amount,'tax_amount'=>$i->tax_amount,'line_total'=>$i->line_total]);return $o->load('items');});return response()->json(['data'=>$order],201);} }
